svg.script:
// Función para manejar los clics en los interruptores

function setupSwitch(switchId, leverId, contactId, highlightId, descId) {
    const switchEl = document.getElementById(switchId);
    const lever = document.getElementById(leverId);
    const contact = document.getElementById(contactId);
    const highlight = document.getElementById(highlightId);
    const desc = document.getElementById(descId);

    let isActive = false;

    switchEl.addEventListener('click', function() {
        // Ocultar todos los highlights y descripciones primero
        document.querySelectorAll('.highlight, .hidden').forEach(el => {
            if (el.id !== highlightId && el.id !== descId) {
                el.setAttribute('height', '0');
                el.classList.add('hidden');
            }
        });

        // Alternar estado
        isActive = !isActive;

        if (isActive) {
            // Mostrar highlight y descripción
            highlight.setAttribute('height', '60');
            desc.classList.remove('hidden');

            // Resaltar el interruptor
            switchEl.style.filter = 'drop-shadow(0 0 5px rgba(241, 196, 15, 0.7))';

            // Animación específica para cada tipo
            if (leverId === 'lever') {
                // Animación de palanca
                lever.setAttribute('transform', 'rotate(30, 50, 30)');
                contact.setAttribute('fill', '#2ecc71');
            } else if (leverId === 'pushbutton') {
                // Animación de pulsador
                lever.setAttribute('cy', '40');
                contact.setAttribute('fill', '#2ecc71');
            } else if (leverId === 'toggle') {
                // Animación de conmutador
                lever.setAttribute('transform', 'rotate(45, 50, 50)');
                contact.setAttribute('fill', '#2ecc71');
            } else if (leverId === 'mercury') {
                // Animación de mercurio
                lever.setAttribute('cy', '50');
            }
        } else {
            // Ocultar highlight y descripción
            highlight.setAttribute('height', '0');
            desc.classList.add('hidden');

            // Quitar resaltado
            switchEl.style.filter = 'none';

            // Restaurar estado inicial
            if (leverId === 'lever') {
                lever.setAttribute('transform', 'rotate(0, 50, 30)');
                contact.setAttribute('fill', '#f1c40f');
            } else if (leverId === 'pushbutton') {
                lever.setAttribute('cy', '20');
                contact.setAttribute('fill', '#f1c40f');
            } else if (leverId === 'toggle') {
                lever.setAttribute('transform', 'rotate(0, 50, 50)');
                contact.setAttribute('fill', '#f1c40f');
            } else if (leverId === 'mercury') {
                lever.setAttribute('cy', '30');
            }
        }
    });
}

// Configurar cada interruptor
setupSwitch('lever-switch', 'lever', 'lever-contact', 'lever-highlight', 'lever-desc');
setupSwitch('pushbutton-na', 'pushbutton', 'pushbutton-contact', 'pushbutton-highlight', 'pushbutton-desc');
setupSwitch('toggle-switch', 'toggle', 'toggle-contact', 'toggle-highlight', 'toggle-desc');
setupSwitch('mercury-switch', 'mercury', '', 'mercury-highlight', 'mercury-desc');
